		private void CheckLoadPlayerModel(int stationIndex, ushort newFashionID, global::System.Action onComplete = null) {
			if (fashionIDArray[stationIndex] == newFashionID)
			{
				ContestUtils.EmitLog(string.Format("Already Load CharacterModel [{0}]: FashionID [{1}]", stationIndex, newFashionID), UnityEngine.LogType.Log);
				onComplete?.Invoke();
				return;
			}

			fashionIDArray[stationIndex] = newFashionID;
			EntryPlayerData entryPlayerData = ContestWork.entryPlayerDatas[stationIndex];
			string modelPath = ContestUtils.CreateTrainerModelPath(newFashionID);
			Dpr.Trainer.TrainerType trainerType = ContestUtils.CreateTrainerType(networkPtr.MyStationIndex == stationIndex, entryPlayerData.playerSex);
			loadCount++;
			contestMatchingUIPtr.LoadCharacterModel(stationIndex, trainerType, entryPlayerData.colorID, modelPath, model =>
			{
				loadCount--;
				onComplete?.Invoke();
			});
		}
		private void OnChangeStateCheckEntryMember() {
			for (int i = 0; i < activeMemberArray.Length; i++)
			{
				if (activeMemberArray[i])
				{
					networkPtr.SetEntryPlayerInfo(i, i == networkPtr.MyStationIndex ? PlayerType.User : PlayerType.Other);
					networkPtr.SetSubFlag(i, true);
					contestMatchingUIPtr.ShowPreparatioIconReady(i);
				}
				else
				{
					networkPtr.SetEntryPlayerInfo(i, PlayerType.NPC);
				}
			}

			contestMatchingUIPtr.HideCountDownTimer();
			contestMatchingUIPtr.CloseContextMenu();
			bIsCountDown = false;
			if (currentJoinNum >= 4)
			{
				ShowGoContestSceneMessage();
				return;
			}

			contestMatchingUIPtr.ShowMessageWindow("DP_contest_678", () =>
			{
				Dpr.NetworkUtils.NetworkManager networkManager = Dpr.NetworkUtils.NetworkManager.Instance;
				for (int i = 0; i < 4; i++)
				{
					if (!networkManager.IsGamerActive(i) && !contestMatchingUIPtr.HasViewModelByIndex(i))
						LoadNPCModel(i, ContestWork.entryPlayerDatas[i].npcDataIndex);
				}
			});
		}
		private void LoadNPCModel(int index, int npcDataIndex) {
			loadCount++;
			ContestMasterDatas.SheetNPCData npcData = contestMasterDatas.NPCData[npcDataIndex];
			TrainerTable.SheetTrainerType trainerTypeData = GameData.DataManager.TrainerTable.TrainerType[npcData.trainerType];
			string modelPath = string.Format("persons/battle/{0}", trainerTypeData.ModelID);
			int colorID = trainerTypeData.TrainerID == Dpr.Trainer.TrainerType.MOTHER ? PlayerWork.colorID : 0;
			contestMatchingUIPtr.LoadCharacterModel(index, (Dpr.Trainer.TrainerType)npcData.trainerType, colorID, modelPath, model =>
			{
				Dpr.Message.MessageMsgFile charactersMsgFile = Dpr.Message.MessageManager.Instance.GetMsgFile("dp_characters");
				contestMatchingUIPtr.SetPlayerName(index, charactersMsgFile.GetNameStr(npcData.trainerLabelName));
				contestMatchingUIPtr.ShowPreparatioIconReady(index);
				loadCount--;
				if (loadCount > 0)
					return;

				ShowGoContestSceneMessage();
			});
		}
		private void ShowGoContestSceneMessage() {
