		private void OnFinishPreparation() {
			if (bIsAlreadyChangeFinishPreparation)
			{
				ContestUtils.EmitLog("Already Change FinishPreparation", UnityEngine.LogType.Log);
				return;
			}

			ContestUtils.EmitLog("OnFinishPreparation", UnityEngine.LogType.Log);
			nowOpenWindow = null;
			contestMatchingUIPtr.HideCountDownTimer();
			if (!bIsActive)
				return;

			ContestWork.ApplyUserDataToEntryPlayerData(networkPtr.MyStationIndex);
			ChangeState(PreparationState.WaitAllMemberPreparation);
			CheckLoadPlayerModel(networkPtr.MyStationIndex, ContestWork.playerFashion, () =>
			{
				ContestUtils.EmitLog(string.Format("OnLoad MyModel : State [{0}]", currentState), UnityEngine.LogType.Log);
				networkPtr.ResetTimer();
				networkPtr.SendNoticeDataToAll(NoticeID.CompletePreparation);
				OnCompletePreparation(networkPtr.MyStationIndex);
			});
