		private T OpenUIWIndow<T>(global::UIWindowID openWindowID, global::System.Action onDecide, global::System.Action onCancel) where T : global::Dpr.UI.UIWindow, global::Dpr.Contest.IContestUIWindow {
			T window = uiManager.CreateUIWindow<T>(openWindowID);
			window.onClosed = (UIWindow win) =>
			{
				if (win is T)
				{
					if (((T)win).ResultEventID == ContestMenuEventID.Decide)
						onDecide?.Invoke();
					else
						onCancel?.Invoke();
				}
			};
			return window;
		}
		private void OnCompletePreparation(int stationIndex) {
