		}
		public void OnChangeHostMine() {
			ContestUtils.EmitLog(string.Format("ChangeHostMine in Preparation : [{0}]", currentState), UnityEngine.LogType.Log);
			switch (currentState)
			{
				case PreparationState.Confirm:
				case PreparationState.UIMenu:
				case PreparationState.WaitAllMemberPreparation:
					networkPtr.SetAllMainFlag(false);
					contestMatchingUIPtr.StartCountDown(contestMatchingUIPtr.CountTime);
					bIsCountDown = true;
					break;
				case PreparationState.WaitHostContestLevel:
					ChangeState(PreparationState.SendContestData);
					break;
			}
		}
