			ContestWork.entryPlayerDatas[0].npcDataIndex = entryNPCData.data.npc1Index;
			ContestWork.entryPlayerDatas[0].npcWazaNo = (Pml.WazaNo)entryNPCData.data.npc1WazaNo;
			ContestWork.entryPlayerDatas[1].npcDataIndex = entryNPCData.data.npc2Index;
			ContestWork.entryPlayerDatas[1].npcWazaNo = (Pml.WazaNo)entryNPCData.data.npc2WazaNo;
			ContestWork.entryPlayerDatas[2].npcDataIndex = entryNPCData.data.npc3Index;
			ContestWork.entryPlayerDatas[2].npcWazaNo = (Pml.WazaNo)entryNPCData.data.npc3WazaNo;
			ContestWork.entryPlayerDatas[3].npcDataIndex = entryNPCData.data.npc4Index;
			ContestWork.entryPlayerDatas[3].npcWazaNo = (Pml.WazaNo)entryNPCData.data.npc4WazaNo;
			ChangeState(PreparationState.LoadingWazaSquence);
		}
		public void OnReceiveEntryPlayerData(int stationIndex) {
			networkPtr.SetMainFlag(stationIndex, true);
		}
		public void OnReceiveContestInfoData(global::Dpr.Contest.ContestInfoNetData contestData) {
			ContestWork.contestStageRank = contestData.data.stageRank;
			bIsReceivedStageRank = true;
		}
		public void OnReceiveReadyData(int stationIndex, global::Dpr.Contest.NoticeID noticeID) {
			switch (noticeID)
			{
				case NoticeID.Ready:
					networkPtr.SetMainFlag(stationIndex, true);
					break;
				case NoticeID.CompletePreparation:
					OnCompletePreparation(stationIndex);
					break;
				case NoticeID.DoNextStep:
					ChangeState(PreparationState.Finish);
					break;
			}
		}
		public ContestMatchingPreparation() { }
		private enum PreparationState
		{
			Confirm = 0,
			UIMenu = 1,
			WaitAllMemberPreparation = 2,
			LoadingWazaSquence = 3,
			SendPlayerData = 4,
			WaitReceivePlayerDatas = 5,
			WaitHostContestLevel = 6,
			SendContestData = 7,
			LoadMemberModel = 8,
			CheckEntryMember = 9,
			WaitAllMemberReady = 10,
			Finish = 11,
		}
		private enum UIMenuState
		{
			PokeSelect = 0,
			WazaSelect = 1,
			CapsuleSelect = 2,
			BoutiqueSelect = 3,
		}
	}
}
